// Voice clips for the Shorts (WO-028): VOICEVOX 春日部つむぎ, generated by tools/make_voice.py into
// apps/shorts/public/voice/<cardId>/<key>.m4a with their text and length in manifest.json. A clip plays
// only while its text still matches the Short's line; a missing or stale clip means a silent line.
import { getCard, loadBundle, shortLines } from '@lens/scenes';
import manifest from '../public/voice/manifest.json';

interface Clip {
  text: string;
  file: string;
  ms: number;
}

const clips = manifest as unknown as Record<string, Record<string, Clip>>;

function current(cardId: string, key: string): Clip | null {
  const clip = clips[cardId]?.[key];
  const card = getCard(cardId);
  if (!clip || !card) return null;
  const line = shortLines(card, loadBundle().labels.lenses[card.lens]?.ja ?? card.lens).find((l) => l.key === key);
  return line && line.speech === clip.text ? clip : null;
}

/** Length of a generated, up-to-date clip in ms (undefined when there is none). */
export function voiceMs(cardId: string, key: string): number | undefined {
  return current(cardId, key)?.ms;
}

/** Path under public/ for staticFile(), or null. */
export function voiceClip(cardId: string, key: string): string | null {
  const clip = current(cardId, key);
  return clip ? `voice/${cardId}/${clip.file}` : null;
}
